            col+=pow(line(c,p[7].xy,p[5].xy),2.2);
            col=pow(col,1./2.2);
            col*=col;
            col*=0.5;
            float3 xnxx = float3(col);
            xnxx *= amzp_color1.rgb;
            sparkx = float4(xnxx,1.0); }
            else {
            float2 index = floor(uv);
         float2 gridUv = fract(uv) - .5;
            float2 px[9];
            int i = 0;
            for(float y =-1. ;y <=1. ; y++)
