                for(float x =-1. ;x <=1. ; x++)
                {
                    px[i++] = GetGridPoint(index, float2(x,y));
                }
            }
            float result = 0.;
            for(int i=0; i< 9; i++)
            {
                result += LineX(gridUv, px[4], px[i]);
            }
            result += LineX(gridUv, px[1], px[3]);
            result += LineX(gridUv, px[1], px[5]);
            result += LineX(gridUv, px[3], px[7]);
            result += LineX(gridUv, px[5], px[7]);
