         r=length(n-w*r);
               return clamp(smoothstep(0.04,0.01,r)*(smoothstep(0.6,1.,1./distance(p,p2))),0.,1.);
        }
        float N21(float2 p)
        {
            p = fract(p*float2(651.34, 237.73));
            p += dot(p, p + 23.45);
            return fract(p.x*p.y);
        }
        float2 N22(float2 p)
        {
            float n = N21(p);
